create type public.entry_kind as enum ('salary','business','freelance','investment','rental','gift','other'); create type public.essentiality as enum ('essential','important','optional'); create type public.debt_status as enum ('open','paid','paused'); create type public.reserve_entry_type as enum ('deposit','withdrawal','adjustment');
create table public.income_entries(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references public.profiles(id),title text not null,amount numeric(14,2) not null check(amount>0),date date not null default current_date,category_id uuid references public.categories(id) on delete set null,income_type public.entry_kind not null default 'other',is_recurring boolean not null default false,recurrence_rule text,emoji text not null default '💵',color text not null default '#55B685',goal_id uuid references public.goals(id) on delete set null,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.expense_entries(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references public.profiles(id),title text not null,amount numeric(14,2) not null check(amount>0),date date not null default current_date,category_id uuid references public.categories(id) on delete set null,expense_type text not null default 'other',essentiality public.essentiality not null default 'important',payment_method text,is_recurring boolean not null default false,recurrence_rule text,emoji text not null default '💸',color text not null default '#FF6B57',notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.debts(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references public.profiles(id),creditor text not null,title text not null,initial_amount numeric(14,2) not null check(initial_amount>=0),interest_rate numeric(7,4) not null default 0,status public.debt_status not null default 'open',emoji text not null default '🤝',color text not null default '#FF6B57',notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.debt_payments(id uuid primary key default gen_random_uuid(),debt_id uuid not null references public.debts(id) on delete cascade,workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references public.profiles(id),amount numeric(14,2) not null check(amount>0),date date not null default current_date,notes text,created_at timestamptz not null default now(),deleted_at timestamptz);
create table public.reserve_entries(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references public.profiles(id),type public.reserve_entry_type not null,amount numeric(14,2) not null check(amount>0),date date not null default current_date,notes text,created_at timestamptz not null default now(),deleted_at timestamptz);
create table public.investments(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references public.profiles(id),name text not null,asset_type text not null,invested_amount numeric(14,2) not null default 0,current_value numeric(14,2) not null default 0,emoji text not null default '📈',color text not null default '#5B8DEF',updated_at timestamptz not null default now(),created_at timestamptz not null default now(),deleted_at timestamptz);
create table public.assets(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references public.profiles(id),name text not null,asset_type text not null,value numeric(14,2) not null default 0,emoji text not null default '🏡',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.business_monthly_metrics(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references public.profiles(id),month date not null, revenue numeric(14,2) not null default 0,expenses numeric(14,2) not null default 0,mrr numeric(14,2) not null default 0,leads integer not null default 0,meetings integer not null default 0,proposals integer not null default 0,sales integer not null default 0,unique(workspace_id,month));
create table public.freedom_criteria(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references public.profiles(id),key text not null, label text not null,target_value numeric(14,2),is_met boolean not null default false,unique(workspace_id,key));
alter table public.income_entries enable row level security;alter table public.expense_entries enable row level security;alter table public.debts enable row level security;alter table public.debt_payments enable row level security;alter table public.reserve_entries enable row level security;alter table public.investments enable row level security;alter table public.assets enable row level security;alter table public.business_monthly_metrics enable row level security;alter table public.freedom_criteria enable row level security;
grant select,insert,update,delete on public.income_entries,public.expense_entries,public.debts,public.debt_payments,public.reserve_entries,public.investments,public.assets,public.business_monthly_metrics,public.freedom_criteria to authenticated;
create policy "income_owner" on public.income_entries for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy "expense_owner" on public.expense_entries for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy "debt_owner" on public.debts for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy "payment_owner" on public.debt_payments for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy "reserve_owner" on public.reserve_entries for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy "investment_owner" on public.investments for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy "asset_owner" on public.assets for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy "business_owner" on public.business_monthly_metrics for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy "freedom_owner" on public.freedom_criteria for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
